var val = Environment.GetEnvironmentVariable("MY_FLAG");
if (val == null)
{
    // .NET 9 breaking change: on Linux, empty env vars previously
    // returned null; now they correctly return "". This null check
    // now properly means "variable is not set at all".
    Console.WriteLine("MY_FLAG not set, using default");
}
else
{
    // val is "" when explicitly set empty (export MY_FLAG="")
    Console.WriteLine($"MY_FLAG is explicitly set to: '{val}'");
}

